package com.voicetxt.reader;
import android.app.Instrumentation;import android.os.Bundle;import android.app.DownloadManager;import android.database.Cursor;import android.content.Context;import com.google.mlkit.nl.translate.*;import com.google.mlkit.common.model.DownloadConditions;import com.google.android.gms.tasks.*;import java.util.concurrent.*;
public class TranslationProbe extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 void prepare(Translator translator)throws Exception{Task<Void> task=translator.downloadModelIfNeeded(new DownloadConditions.Builder().requireWifi().build());long until=android.os.SystemClock.elapsedRealtime()+8*60*1000;long reportAt=0;while(!task.isComplete()){long now=android.os.SystemClock.elapsedRealtime();if(now>until)throw new java.io.IOException("translation model download timeout");if(now>reportAt){Bundle progress=new Bundle();progress.putString("stage","downloading offline translation model on Wi-Fi");DownloadManager manager=(DownloadManager)getTargetContext().getSystemService(Context.DOWNLOAD_SERVICE);try(Cursor rows=manager.query(new DownloadManager.Query())){StringBuilder summary=new StringBuilder();while(rows!=null&&rows.moveToNext()){summary.append("status=").append(rows.getInt(rows.getColumnIndexOrThrow(DownloadManager.COLUMN_STATUS))).append(" reason=").append(rows.getInt(rows.getColumnIndexOrThrow(DownloadManager.COLUMN_REASON))).append(" bytes=").append(rows.getLong(rows.getColumnIndexOrThrow(DownloadManager.COLUMN_BYTES_DOWNLOADED_SO_FAR))).append('/').append(rows.getLong(rows.getColumnIndexOrThrow(DownloadManager.COLUMN_TOTAL_SIZE_BYTES))).append(';');}progress.putString("downloads",summary.toString());}catch(Exception ignored){}sendStatus(1,progress);reportAt=now+10000;}Thread.sleep(100);}if(!task.isSuccessful())throw task.getException();}
 public void onStart(){Bundle result=new Bundle();Translator cn=Translation.getClient(new TranslatorOptions.Builder().setSourceLanguage("en").setTargetLanguage("zh").build());Translator en=Translation.getClient(new TranslatorOptions.Builder().setSourceLanguage("zh").setTargetLanguage("en").build());try{SystemSpeaker system=new SystemSpeaker(getTargetContext());CountDownLatch ready=new CountDownLatch(1);system.init(()->{if(system.initialized)ready.countDown();});if(!ready.await(30,TimeUnit.SECONDS))throw new IllegalStateException("voice enumeration timeout");int english=0;for(SystemSpeaker.Option option:system.options)if("en".equals(option.voice.getLocale().getLanguage())&&!option.voice.isNetworkConnectionRequired())english++;result.putInt("offlineEnglishVoices",english);system.close();prepare(cn);prepare(en);result.putString("englishToChinese",Tasks.await(cn.translate("The little horse is reading a book. The sun is shining today."),30,TimeUnit.SECONDS));result.putString("chineseToEnglish",Tasks.await(en.translate("小马正在看书。今天阳光明媚。"),30,TimeUnit.SECONDS));result.putString("result","PASS: downloaded translation pack and ran both directions on device");finish(-1,result);}catch(Throwable e){result.putString("error",android.util.Log.getStackTraceString(e));finish(0,result);}finally{cn.close();en.close();}}
}
